--------------------------------------------------
-- LOOKUP HELPERS
--------------------------------------------------

-- Reverse map: numericId -> itemId
ConsumableData._byNumericId = {}
for itemId, def in pairs(ConsumableData.Items) do
	ConsumableData._byNumericId[def.numericId] = itemId
end

function ConsumableData.GetById(id)
	return ConsumableData.Items[id]
end

function ConsumableData.GetByNumericId(numId)
	local itemId = ConsumableData._byNumericId[numId]
	if itemId then
		return ConsumableData.Items[itemId], itemId
	end
	return nil, nil
end

function ConsumableData.GetAllIds()
	local ids = {}
	for id in pairs(ConsumableData.Items) do
		ids[#ids + 1] = id
	end
	table.sort(ids)
	return ids
end

function ConsumableData.GetByCategory(category)
	local results = {}
	for id, def in pairs(ConsumableData.Items) do
		if def.category == category then
			results[id] = def
		end
	end
	return results
end

function ConsumableData.GetByTier(tier)
	local results = {}
	for id, def in pairs(ConsumableData.Items) do
		if def.tier == tier then
			results[id] = def
		end
	end
	return results
end

return ConsumableData
